// Log in.
const cfg = {
    url: env.get('SDI_ODOO_URL') || '',
    db: env.get('SDI_ODOO_DB') || '',
    user: env.get('SDI_ODOO_USER') || '',
    key: env.get('SDI_ODOO_APIKEY') || '',
    aas: env.get('SDI_AAS_URL') || 'http://localhost:8081',
    basis: env.get('SDI_AAS_BASE') || 'localhost/demo/aas'
};
if (!cfg.key) { node.error('No Odoo API key in the environment.'); return null; }
flow.set('cfg', cfg);
msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'common', method: 'login', args: [cfg.db, cfg.user, cfg.key] } };
return msg;

// Fetches the articles, so components can be named later on.
const cfg = flow.get('cfg');
const uid = (msg.payload || {}).result;
if (!uid) { node.error('Login failed'); return null; }
flow.set('uid', uid);
msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'product.product', 'search_read',
           [[]], { fields: ['default_code'], limit: 100 }] } };
return msg;

// Fetches every completed order for the assembled product.
const cfg = flow.get('cfg');
const uid = flow.get('uid');
if ((msg.payload || {}).error) {
    node.error('Odoo reports: ' + ((msg.payload.error.data) || {}).message);
    return null;
}
const nachId = {};
for (const v of ((msg.payload || {}).result || [])) { nachId[v.id] = v.default_code; }
flow.set('artikelNachId', nachId);

const ERZEUGNIS = env.get('SDI_ASSEMBLY_ARTICLE') || '000114';
const stift = Object.keys(nachId).find(function (id) {
    return nachId[id] === ERZEUGNIS;
});
msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'mrp.production', 'search_read',
           [[['product_id', '=', Number(stift)], ['state', '=', 'done']]],
           { fields: ['name', 'date_finished', 'lot_producing_ids',
                      'move_raw_line_ids'], limit: 50 }] } };
return msg;

// Fetches the consumption lines of all orders in one request.
const cfg = flow.get('cfg');
const uid = flow.get('uid');
if ((msg.payload || {}).error) {
    node.error('Manufacturing orders: ' + ((msg.payload.error.data) || {}).message);
    return null;
}
const auftraege = (msg.payload || {}).result || [];
flow.set('auftraege', auftraege);
node.warn('Completed manufacturing orders: ' + auftraege.length);
if (!auftraege.length) { return null; }

let zeilen = [];
let lose = [];
for (const a of auftraege) {
    zeilen = zeilen.concat(a.move_raw_line_ids || []);
    lose = lose.concat(a.lot_producing_ids || []);
}
flow.set('loseIds', lose);
msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'stock.move.line', 'read',
           [zeilen, ['product_id', 'lot_id', 'quantity']]] } };
return msg;

// Fetches the names of the serial numbers of the assembled pieces.
const cfg = flow.get('cfg');
const uid = flow.get('uid');
if ((msg.payload || {}).error) {
    node.error('Consumption lines: ' + ((msg.payload.error.data) || {}).message);
    return null;
}
const nachZeile = {};
for (const z of ((msg.payload || {}).result || [])) { nachZeile[z.id] = z; }
flow.set('zeilenNachId', nachZeile);

msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'stock.lot', 'read',
           [flow.get('loseIds') || [], ['name']]] } };
return msg;

// Fetches the shell of the assembled product.
const cfg = flow.get('cfg');
if ((msg.payload || {}).error) {
    node.error('Serial numbers: ' + ((msg.payload.error.data) || {}).message);
    return null;
}
const nachId = {};
for (const l of ((msg.payload || {}).result || [])) { nachId[l.id] = l.name; }
flow.set('losNamen', nachId);

function b64(text) {
    return Buffer.from(text, 'utf8').toString('base64')
        .split('+').join('-').split('/').join('_').split('=').join('');
}
const PRODUKT = env.get('SDI_LCA_PRODUCT') || 'Kugelschreiber_TracePEN';
flow.set('kennung', b64(cfg.basis + '/' + PRODUKT + '/DataSources'));
msg.url = cfg.aas + '/submodels/' + flow.get('kennung');
msg.method = 'GET';
msg.headers = { 'Accept': 'application/json' };
msg.payload = '';
return msg;

// Records every order as an entry under AssemblyRecords.
const cfg = flow.get('cfg');
const auftraege = flow.get('auftraege') || [];
const zeilen = flow.get('zeilenNachId') || {};
const losNamen = flow.get('losNamen') || {};
const artikel = flow.get('artikelNachId') || {};
const sm = msg.payload;
if (!sm || !sm.submodelElements) { node.error('Shell cannot be read'); return null; }

const prop = function (id, v, t) {
    return { modelType: 'Property', idShort: id, valueType: t || 'xs:string',
             value: v === null || v === undefined ? '' : String(v) };
};
// Members of a list carry no idShort (AASd-120).
const glied = function (v) {
    return { modelType: 'SubmodelElementCollection', value: v };
};
const sml = function (id, v) {
    return { modelType: 'SubmodelElementList', idShort: id,
             typeValueListElement: 'SubmodelElementCollection',
             orderRelevant: false, value: v };
};

let liste = null;
for (const e of sm.submodelElements) {
    if (e.idShort === 'DataSources') { liste = e; }
}
const erp = ((liste || {}).value || []).find(function (e) {
    return e.idShort === 'ERP' || e.idShort === 'ERPData';
});
if (!erp) { node.error('No ERP data source in the shell'); return null; }

let sammlung = (erp.value || []).find(function (x) {
    return x && x.idShort === 'AssemblyRecords';
});
if (!sammlung) { sammlung = sml('AssemblyRecords', []); erp.value.push(sammlung); }

function nummerVon(eintrag) {
    const n = (eintrag.value || []).find(function (y) { return y.idShort === 'SerialNumber'; });
    return n ? String(n.value) : '';
}

let neu = 0;
for (const a of auftraege) {
    const stueck = losNamen[(a.lot_producing_ids || [])[0]] || '';
    if (!stueck) { continue; }
    const teile = [];
    for (const zid of (a.move_raw_line_ids || [])) {
        const z = zeilen[zid];
        if (!z) { continue; }
        const nummer = (z.lot_id || [])[1] || '';
        if (!nummer) { continue; }
        teile.push(glied([
            prop('ArticleNumber', artikel[(z.product_id || [])[0]] || ''),
            prop('SerialNumber', nummer),
            prop('Quantity', z.quantity, 'xs:double')
        ]));
    }
    const eintrag = glied([
        prop('ManufacturingOrder', a.name || ''),
        prop('SerialNumber', stueck),
        prop('TimeOfBooking', (a.date_finished || '').replace(' ', 'T') + 'Z',
             'xs:dateTime'),
        prop('BookedComponents', String(teile.length), 'xs:int'),
        sml('InstalledComponents', teile)
    ]);
    sammlung.value = (sammlung.value || []).filter(function (x) {
        return nummerVon(x) !== stueck;
    });
    sammlung.value.push(eintrag);
    neu = neu + 1;
    node.warn('   ' + stueck + ' from ' + a.name + ', ' + teile.length + ' components');
}
node.warn('Recorded: ' + neu + ' pieces');

msg.url = cfg.aas + '/submodels/' + flow.get('kennung');
msg.method = 'PUT';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = sm;
return msg;

// Reports that the run is done.
node.warn('Assembly records restored.');
return null;
